import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"en/changelog.md","lastUpdated":null}'),n={name:"changelog.md"};function d(r,e,l,c,s,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="vnext-2026" tabindex="-1">vNext (2026--) <a class="header-anchor" href="#vnext-2026" aria-label="Permalink to &quot;vNext (2026--)&quot;">​</a></h2><ul><li>Publish only <code>dist</code> next to <code>package.json</code>, <code>README.md</code> and <code>LICENSE</code>, so a folder outside the package can no longer end up in it, as a local <code>.claude</code> folder did in 1.4.0 and made it 32 MB</li></ul><h2 id="_1-5-0-2026-11-05" tabindex="-1">1.5.0 (2026-11-05) <a class="header-anchor" href="#_1-5-0-2026-11-05" aria-label="Permalink to &quot;1.5.0 (2026-11-05)&quot;">​</a></h2><p>Merge behavior has changed. An entry that the VitePress options already have under the same key in <code>locales</code> now takes precedence over the built-in translations and the shared <code>themeConfig</code> instead of being overwritten by them. The same now holds for the <code>locales</code> entries of the search options. Sites that relied on the plugin replacing those values may see different output.</p><p>The shape of the output has changed as well. A shared <code>themeConfig</code> key is copied into a locale only when that locale sets the same key, such as a translated label or a per locale override, and every other key stays at the top level. VitePress lays the locale <code>themeConfig</code> over the shared one, so pages render the same, but code that reads a shared value such as <code>nav</code> from <code>locales[key].themeConfig</code> has to read it from <code>themeConfig</code> instead.</p><ul><li>Add <code>rootLocale: false</code> to keep every language in its own directory without a <code>root</code> locale (#12)</li><li>Fix the values of an existing <code>locales</code> entry, such as its <code>label</code> or <code>themeConfig.nav</code>, being overwritten by the built-in translations and the shared <code>themeConfig</code> (#12)</li><li>Stop copying the whole shared <code>themeConfig</code> into every locale, which grew the site data that every page loads with each added language and kept a stale copy of a <code>sidebar</code> set by a plugin running after <code>withI18n</code></li><li>Fix the translated outline title falling back to English when <code>outline</code> is set to a heading level only, such as <code>&#39;deep&#39;</code> or <code>[2, 3]</code></li><li>Let the deprecated <code>outlineTitle</code> and <code>lastUpdatedText</code> beat the built-in translations like the other shared values, instead of being hidden by them</li><li>Fix the <code>editLink</code> text falling back to English when only a per locale <code>themeConfig</code> sets the <code>pattern</code></li><li>Keep the <code>locales</code> entries of the search options, which were replaced as a whole and lost settings such as a per locale Algolia <code>indexName</code> or <code>searchParameters</code></li><li>Remove the slashes around a <code>path</code>, which turned <code>/ko/</code> into a locale that never matched a page, and reject an empty <code>path</code> outside the root locale</li><li><code>debugPrint</code> prints <code>locales</code> and <code>themeConfig</code> after the merge with the VitePress options, so entries the plugin did not generate show up as well (#12)</li><li>Fix the spanish search button and Algolia search input label reading <code>Buscar en</code> (&quot;Search in&quot;) instead of <code>Buscar</code></li><li>Fix the spanish local search showing <code>Cerrar búsqueda</code> (&quot;Close search&quot;) instead of <code>Sin resultados para</code> when nothing matches</li></ul><h2 id="_1-4-0-2026-08-25" tabindex="-1">1.4.0 (2026-08-25) <a class="header-anchor" href="#_1-4-0-2026-08-25" aria-label="Permalink to &quot;1.4.0 (2026-08-25)&quot;">​</a></h2><p>Merge behavior has changed. A per locale <code>themeConfig</code> now overrides the shared one instead of losing to it, and <code>themeConfig</code> arrays such as <code>nav</code> are replaced by the more specific value instead of being merged entry by entry. Sites that relied on the previous order may see different output.</p><ul><li>Add <code>notFound</code> page and <code>skipToContentLabel</code> translations for every language</li><li>Allow either the directory path or the language code as the key of the per language options (<code>label</code>, <code>link</code>, <code>lang</code>, <code>title</code>, <code>titleTemplate</code>, <code>description</code>, <code>head</code>, <code>themeConfig</code>)</li><li>Fix <code>withI18n</code> writing into the shared translation constants, which crashed the next call with <code>TypeError</code> and could take down the dev server</li><li>Fix search translations not being applied when the provider is set through <code>themeConfig</code> (#9)</li><li>Fix a per locale <code>themeConfig</code> being overwritten by the shared one</li><li>Fix <code>themeConfig</code> arrays gaining <code>null</code> entries when both sides mixed value types</li><li>Fix the shared <code>head</code> being copied into every locale, which duplicated <code>link</code>, <code>script</code> and <code>style</code> tags on every page</li><li>Fix <code>titleTemplate</code> being dropped when set to <code>false</code></li><li>Fix <code>withI18n</code> writing back into the two options objects passed to it</li><li>Reject a <code>rootLocale</code> that is missing from <code>locales</code>, and two locales resolving to the same key</li><li>Report the format error instead of a <code>TypeError</code> for a malformed <code>locales</code> entry</li><li>Remove the hardcoded GitHub name from the chinese simplified, spanish and portuguese <code>editLink</code> texts</li><li>Fix mistranslated german, italian, vietnamese, indonesian, spanish, portuguese, japanese and chinese traditional strings</li><li>Resolve supported locales through a lookup map instead of repeated linear scans</li></ul><h2 id="_1-3-5-2025-12-18" tabindex="-1">1.3.5 (2025-12-18) <a class="header-anchor" href="#_1-3-5-2025-12-18" aria-label="Permalink to &quot;1.3.5 (2025-12-18)&quot;">​</a></h2><ul><li>Fix search box does not work when themeConfig search provider is set (#9)</li></ul><h2 id="_1-3-4-2025-04-26" tabindex="-1">1.3.4 (2025-04-26) <a class="header-anchor" href="#_1-3-4-2025-04-26" aria-label="Permalink to &quot;1.3.4 (2025-04-26)&quot;">​</a></h2><ul><li>Fixed some common themeConfig settings not being merged (#8)</li></ul><h2 id="_1-3-3-2025-03-13" tabindex="-1">1.3.3 (2025-03-13) <a class="header-anchor" href="#_1-3-3-2025-03-13" aria-label="Permalink to &quot;1.3.3 (2025-03-13)&quot;">​</a></h2><ul><li>Do not include in the options when <code>editLink</code> is not defined (#6)</li></ul><h2 id="_1-3-2-2025-03-03" tabindex="-1">1.3.2 (2025-03-03) <a class="header-anchor" href="#_1-3-2-2025-03-03" aria-label="Permalink to &quot;1.3.2 (2025-03-03)&quot;">​</a></h2><ul><li>Update french translations (@paul-louyot)</li></ul><h2 id="_1-3-1-2024-12-07" tabindex="-1">1.3.1 (2024-12-07) <a class="header-anchor" href="#_1-3-1-2024-12-07" aria-label="Permalink to &quot;1.3.1 (2024-12-07)&quot;">​</a></h2><ul><li>Fix import of type declaration files</li></ul><h2 id="_1-3-0-2024-10-24" tabindex="-1">1.3.0 (2024-10-24) <a class="header-anchor" href="#_1-3-0-2024-10-24" aria-label="Permalink to &quot;1.3.0 (2024-10-24)&quot;">​</a></h2><ul><li><strong>BREAKING CHANGES</strong>: There have been significant changes to how this plugin is used. Learn more by visiting the following documentation pages: <a href="https://vitepress-i18n.cdget.com" target="_blank" rel="noreferrer">https://vitepress-i18n.cdget.com</a></li></ul><h2 id="_1-2-0-2024-10-24" tabindex="-1">1.2.0 (2024-10-24) <a class="header-anchor" href="#_1-2-0-2024-10-24" aria-label="Permalink to &quot;1.2.0 (2024-10-24)&quot;">​</a></h2><p>This version is deprecated and not recommended for production use.</p><ul><li><strong>BREAKING CHANGES</strong>: The <code>generateI18nLocale</code> and <code>generateI18nSearch</code> functions have now been merged into <code>withI18n</code>. Therefore, both functions will be removed in the next version. Please refer to the documentation to migrate to the <code>withI18n</code> function.</li></ul><h2 id="_1-1-1-2024-10-23" tabindex="-1">1.1.1 (2024-10-23) <a class="header-anchor" href="#_1-1-1-2024-10-23" aria-label="Permalink to &quot;1.1.1 (2024-10-23)&quot;">​</a></h2><p>This version is deprecated and not recommended for production use.</p><ul><li>Fix chinese simplified string (#1)</li></ul><h2 id="_1-1-0-2024-10-23" tabindex="-1">1.1.0 (2024-10-23) <a class="header-anchor" href="#_1-1-0-2024-10-23" aria-label="Permalink to &quot;1.1.0 (2024-10-23)&quot;">​</a></h2><p>This version is deprecated and not recommended for production use.</p><ul><li><strong>BREAKING CHANGES</strong>: The <code>generateI18nLocale</code> and <code>generateI18nSearch</code> functions have now been merged into <code>generateI18n</code>. Therefore, both functions will be removed in the next version. Please refer to the documentation to migrate to the <code>generateI18n</code> function.</li></ul><h2 id="_1-0-6-2024-09-16" tabindex="-1">1.0.6 (2024-09-16) <a class="header-anchor" href="#_1-0-6-2024-09-16" aria-label="Permalink to &quot;1.0.6 (2024-09-16)&quot;">​</a></h2><p>This version is deprecated and not recommended for production use.</p><ul><li>Override <code>editLinkPattern</code> value even if defined common theme configs</li><li>Add <code>debugPrint</code> option for <code>generateI18nSearch</code></li></ul><h2 id="_1-0-5-2024-09-16-not-for-production" tabindex="-1">1.0.5 (2024-09-16) - Not for Production <a class="header-anchor" href="#_1-0-5-2024-09-16-not-for-production" aria-label="Permalink to &quot;1.0.5 (2024-09-16) - Not for Production&quot;">​</a></h2><ul><li>Add italian translations</li><li>Allow auto set lang and label value when if not defined</li><li>Add <code>debugPrint</code> method</li><li>Add <code>disableAutoSetLangValue</code> method</li></ul><h2 id="_1-0-4-2024-09-07-not-for-production" tabindex="-1">1.0.4 (2024-09-07) - Not for Production <a class="header-anchor" href="#_1-0-4-2024-09-07-not-for-production" aria-label="Permalink to &quot;1.0.4 (2024-09-07) - Not for Production&quot;">​</a></h2><ul><li>Fix import issue</li></ul><h2 id="_1-0-3-2024-09-07-not-for-production" tabindex="-1">1.0.3 (2024-09-07) - Not for Production <a class="header-anchor" href="#_1-0-3-2024-09-07-not-for-production" aria-label="Permalink to &quot;1.0.3 (2024-09-07) - Not for Production&quot;">​</a></h2><ul><li>Add chinese traditional, japanese, spanish, portuguese, russian, indonesian, german, french, vietnamese translations</li><li>Split translation and type files</li></ul><h2 id="_1-0-2-2024-09-06-not-for-production" tabindex="-1">1.0.2 (2024-09-06) - Not for Production <a class="header-anchor" href="#_1-0-2-2024-09-06-not-for-production" aria-label="Permalink to &quot;1.0.2 (2024-09-06) - Not for Production&quot;">​</a></h2><ul><li>Add chinese simplified translation</li></ul><h2 id="_1-0-1-2024-09-04-not-for-production" tabindex="-1">1.0.1 (2024-09-04) - Not for Production <a class="header-anchor" href="#_1-0-1-2024-09-04-not-for-production" aria-label="Permalink to &quot;1.0.1 (2024-09-04) - Not for Production&quot;">​</a></h2><ul><li>Minor improvements</li></ul><h2 id="_1-0-0-2024-09-04-not-for-production" tabindex="-1">1.0.0 (2024-09-04) - Not for Production <a class="header-anchor" href="#_1-0-0-2024-09-04-not-for-production" aria-label="Permalink to &quot;1.0.0 (2024-09-04) - Not for Production&quot;">​</a></h2><p>Not purpose for release. Do not use production.</p><ul><li>Initial release</li></ul>',47)])])}const g=o(n,[["render",d]]);export{p as __pageData,g as default};
